reproduction.measurement_script:
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { parseFramingPlan } from './src/lib/import/framing-plan/parse.ts';
import { recoverRows, compact, verticalRuns } from './src/lib/import/runs.ts';
const names = ['ina-p7','shibata-p13','karatsu-jikugumi2-p1','karatsu-fukuzu-p1','karatsu-hashirashin-p1','ina-p6'];
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const pages = Object.fromEntries(names.map(name => {
  const file = 'tests/fixtures/section-import/textitems/' + name + '.json';
  const bytes = readFileSync(file);
  const fixture = JSON.parse(bytes.toString());
  const output = parseFramingPlan({...fixture.page, items: fixture.items});
  const segments = recoverRows(fixture.items).flatMap(row => row.segments.map(s => ({text:compact(s.text), x:s.centerX, y:s.centerY})));
  const vertical = verticalRuns(fixture.items).map(r => ({text:compact(r.text), ...r}));
  const joined = compact(fixture.items.map(i=>i.str).join(''));
  const titleTokens = segments.filter(s => /\u4f0f\u56f3|\u67f1\u82af\u7dda\u56f3/.test(s.text));
  const relevantText = segments.filter(s => /\u8ef8\u7d44\u56f3|\u901a\u308a|\u30ea\u30b9\u30c8|\u4e3b\u7b4b|8-D22|HOOP|^C1$/.test(s.text));
  const blocks = output.blocks.map(b => ({
    title: b.title ?? null,
    x: {labels:b.xGrid.axes.map(a=>a.label),spansMm:b.xGrid.spansMm,totalConfirmed:b.xGrid.totalConfirmed, spanSumMm:b.xGrid.spansMm.reduce((a,b)=>a+b,0)},
    y: {labels:b.yGrid.axes.map(a=>a.label),spansMm:b.yGrid.spansMm,totalConfirmed:b.yGrid.totalConfirmed, spanSumMm:b.yGrid.spansMm.reduce((a,b)=>a+b,0)},
    placement_count:b.placements.length,
    mark_counts:b.placements.reduce((acc,p)=>({...acc,[p.mark]:(acc[p.mark]??0)+1}),{})
  }));
  return [name, {file, fixture_sha256:sha(bytes), page:fixture.page, output, blocks,
    joined_text_has_fukuzu:joined.includes('\u4f0f\u56f3'),
    joined_text_has_hashirashinzu:joined.includes('\u67f1\u82af\u7dda\u56f3'),
    title_tokens:titleTokens, relevant_text:relevantText,
    vertical_title_text:vertical.filter(s=>/\u4f0f\u56f3|\u67f1\u82af\u7dda\u56f3|\u8ef8\u7d44\u56f3/.test(s.text))
  }];
}));
const report = {
 phase:'42-plan-grid-soundness', step:2, name:'document-open-items', status:'in_progress',
 baseline_commit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),
 measurement:{method:'Read unchanged TextItem fixtures; call parseFramingPlan; count returned blocks and placements. Titles are checked in compact item text, recovered row segments and vertical runs.', parser_sha256:sha(readFileSync('src/lib/import/framing-plan/parse.ts')), pages},
 paths_verified:names.map(n=>'tests/fixtures/section-import/textitems/'+n+'.json'),
 paths_expected_absent:[]
};
writeFileSync('phases/42-plan-grid-soundness/step2-report.json', JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(Object.fromEntries(Object.entries(pages).map(([name,p])=>[name,{blocks:p.blocks, title_tokens:p.title_tokens,relevant_text:p.relevant_text,joined_text_has_fukuzu:p.joined_text_has_fukuzu,joined_text_has_hashirashinzu:p.joined_text_has_hashirashinzu}])),null,2));
